import os
from datetime import datetime, timedelta, timezone
from typing import Any, Dict, List, Optional, Union

import boto3


def _coerce_dt(value: Optional[Union[str, datetime]]) -> datetime:
    if value is None:
        return datetime.now(timezone.utc)
    if isinstance(value, datetime):
        return value if value.tzinfo else value.replace(tzinfo=timezone.utc)
    s = value.strip()
    if s.endswith("Z"):
        s = s[:-1] + "+00:00"
    dt = datetime.fromisoformat(s)
    return dt if dt.tzinfo else dt.replace(tzinfo=timezone.utc)


def _period_for_window(start: datetime, end: datetime) -> int:
    seconds = max(int((end - start).total_seconds()), 1)
    if seconds <= 3600:
        return 60
    if seconds <= 6 * 3600:
        return 300
    if seconds <= 24 * 3600:
        return 900
    return 3600


def query_recent_metric_datapoints(
    metric_name: str,
    namespace: str,
    dimensions: Optional[List[Dict[str, str]]] = None,
    start_time: Optional[Union[str, datetime]] = None,
    end_time: Optional[Union[str, datetime]] = None,
    region_name: Optional[str] = None,
    statistic: str = "Average",
    unit: Optional[str] = None,
) -> List[Dict[str, Any]]:
    """
    Query recent datapoints for a CloudWatch metric over a time window.

    Parameters:
        metric_name: CloudWatch metric name.
        namespace: CloudWatch namespace, e.g. "AWS/EC2".
        dimensions: Optional list of {"Name": "...", "Value": "..."} dicts.
        start_time: Window start (ISO string or datetime). Defaults to now - 1 hour.
        end_time: Window end (ISO string or datetime). Defaults to now.
        region_name: AWS region, defaults to AWS_REGION/AWS_DEFAULT_REGION.
        statistic: CloudWatch statistic, e.g. "Average", "Sum", "Maximum".
        unit: Optional CloudWatch unit filter.

    Returns:
        A list of datapoint dicts sorted by Timestamp ascending.
    """
    end_dt = _coerce_dt(end_time)
    start_dt = _coerce_dt(start_time) if start_time is not None else end_dt - timedelta(hours=1)

    region = (
        region_name
        or os.environ.get("AWS_REGION")
        or os.environ.get("AWS_DEFAULT_REGION")
    )
    client = boto3.client("cloudwatch", region_name=region)

    get_metric_data = getattr(client, "get_metric_data", None)
    if get_metric_data is None:
        raise RuntimeError("boto3 CloudWatch client does not support get_metric_data")

    period = _period_for_window(start_dt, end_dt)

    query: Dict[str, Any] = {
        "Id": "m1",
        "MetricStat": {
            "Metric": {
                "Namespace": namespace,
                "MetricName": metric_name,
                "Dimensions": dimensions or [],
            },
            "Period": period,
            "Stat": statistic,
        },
        "ReturnData": True,
    }
    if unit:
        query["MetricStat"]["Unit"] = unit

    response = client.get_metric_data(
        MetricDataQueries=[query],
        StartTime=start_dt,
        EndTime=end_dt,
        ScanBy="TimestampAscending",
    )

    results = response.get("MetricDataResults", [])
    datapoints: List[Dict[str, Any]] = []

    for result in results:
        timestamps = result.get("Timestamps", [])
        values = result.get("Values", [])
        for ts, val in zip(timestamps, values):
            datapoint = {
                "Timestamp": ts,
                "Value": val,
                "Id": result.get("Id"),
                "Label": result.get("Label"),
                "StatusCode": result.get("StatusCode"),
            }
            if "Messages" in result:
                datapoint["Messages"] = result["Messages"]
            datapoints.append(datapoint)

    datapoints.sort(key=lambda x: x["Timestamp"])
    return datapoints


if __name__ == "__main__":
    metric = os.environ.get("CW_METRIC_NAME", "CPUUtilization")
    namespace = os.environ.get("CW_NAMESPACE", "AWS/EC2")
    print(
        query_recent_metric_datapoints(
            metric_name=metric,
            namespace=namespace,
        )
    )
